def draw_Eyebrow(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, '基础', '基础', 0, None, True)
    if g0 is not None:
        kit.texture(g0, p, 'p_DiffuseMap', 'Base Map', None, None)
        kit.texture(g0, p, 'p_BaseMap', 'Albedo', 't_BaseMap', 'o_BaseMap')
        kit.texture(g0, p, 'p_BumpMap', 'Normal Map', None, None)
        kit.texture(g0, p, 'p_RMOSMap', 'RMOS Map (R=Rough G=Metal B=Occ A=Spec)', None, None)
        kit.prop(g0, p, 'p_BaseColor', 'Color')
        kit.prop(g0, p, 'p_BumpScale', 'Normal Scale')
        kit.prop(g0, p, 'p_RoughnessIntensity', 'Roughness Intensity')
        kit.prop(g0, p, 'p_MetallicIntensity', 'Metallic Intensity')
        kit.prop(g0, p, 'p_SpecularIntensity', 'Specular Intensity')
        kit.prop(g0, p, 'p_SurfaceType', 'Surface Type')
        kit.prop(g0, p, 'p_UseRMOSMap', 'Use RMOS Map')
        kit.prop(g0, p, 'p_UseBumpMap', 'Use Normal Map')
        kit.prop(g0, p, 'p_DarkColor', 'Dark Color')
        kit.prop(g0, p, 'p_DayColor', 'Color')
        kit.prop(g0, p, 'p_UseVertexColorForColor', 'Use Vertex Color(G) For Color')
    g1 = kit.group(root, p, 'State', 'State', 0, None, True)
    if g1 is not None:
        kit.prop(g1, p, 'p_Cull', 'Cull')

